-- « Ordonnances à signer » (LecteurOrdonnancesASigner, EcrivainOrdonnancesASigner), lot 10 du plan « RIG v3 100 % fonctionnel »
-- (plan-676a4b19). Identifiants 2 000 1xx, roles 2026OS201xx. Une decision par case de la recherche de RIG v2 (OPE_LISTE_ORDONNANCES.cs)
-- et son jumeau ecarte ; ce qui est retenu ou ecarte, et pourquoi : PROC_ORDOSIGN.attendu. Types de RIG_DEV (lu le 27/11/2026).
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_SAISINE_GREFFE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_SAISINE_GREFFE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_PRCLL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_PRCLL int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_PREVE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_PREVE int NULL;
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL, DCJDC_NUM_ORDRE smallint NOT NULL,
        DCJDC_DATE_PREVUE datetime NULL, DCJDC_DATE datetime NULL, DCJDC_TYPE_DECISION varchar(10) NULL);
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_NUM_REPERTOIRE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_NUM_REPERTOIRE varchar(10) NULL;
IF OBJECT_ID(N'v2.TYPE_DECISION') IS NULL
    CREATE TABLE v2.TYPE_DECISION (R_TYPEDECISI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_TYPEDECISI_LIBELLE_ECRAN varchar(100) NOT NULL);
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_NUM_REPERTOIRE') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_NUM_REPERTOIRE varchar(6) NULL;
IF OBJECT_ID(N'v2.RELANCE_RCS') IS NULL
    CREATE TABLE v2.RELANCE_RCS (RLCRC_ID_RLCRC int NOT NULL PRIMARY KEY, RLCRC_ID_DLGRC int NULL, RLCRC_NUM_ORDRE smallint NOT NULL,
        RLCRC_DATE_RELANCE datetime NOT NULL, RLCRC_DATE_LIMITE datetime NULL);
IF COL_LENGTH('v2.RELANCE_RCS', 'RLCRC_ID_INSTN') IS NULL ALTER TABLE v2.RELANCE_RCS ADD RLCRC_ID_INSTN int NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_EN_COURS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_EN_COURS bit NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM_UTILISATEUR') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM_UTILISATEUR varchar(255) NULL;
IF OBJECT_ID(N'v2.DOSSIER_DEMANDE') IS NULL
    CREATE TABLE v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM int NOT NULL PRIMARY KEY, DSSDM_ID_DMND int NOT NULL,
        DSSDM_CODE_SEQUENCEUR varchar(20) NOT NULL, DSSDM_VALEUR_SEQUENCEUR varchar(100) NULL);
IF OBJECT_ID(N'v2.ETAT_DEMANDE') IS NULL
    CREATE TABLE v2.ETAT_DEMANDE (R_ETATDEMAND_VALEUR varchar(1) NOT NULL PRIMARY KEY, R_ETATDEMAND_LIBELLE_ECRAN varchar(35) NOT NULL);
-- Les natures de diligence et leurs codes affaire (NATURE_DILIGENCE_PARAM, CritereMetier CodeAffaire) : SDCA, SDBE, et une du groupe
-- JugeCommis. NATURE_DILIGENCE vient de PROC_MDIL.sql (joue avant) ; le groupe s'ajoute ici.
IF OBJECT_ID(N'v2.NATURE_DILIGENCE') IS NULL
    CREATE TABLE v2.NATURE_DILIGENCE (R_NATUREDILI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_NATUREDILI_LIBELLE_ECRAN varchar(100) NULL);
IF COL_LENGTH('v2.NATURE_DILIGENCE', 'R_NATUREDILI_ID_NDILGRP') IS NULL ALTER TABLE v2.NATURE_DILIGENCE ADD R_NATUREDILI_ID_NDILGRP int NULL;
IF OBJECT_ID(N'v2.NATURE_DILIGENCE_GROUPE') IS NULL
    CREATE TABLE v2.NATURE_DILIGENCE_GROUPE (NDILGRP_ID_NDILGRP int NOT NULL PRIMARY KEY, NDILGRP_CODE varchar(50) NOT NULL, NDILGRP_LIBELLE varchar(255) NULL);
IF OBJECT_ID(N'v2.NATURE_DILIGENCE_PARAM') IS NULL
    CREATE TABLE v2.NATURE_DILIGENCE_PARAM (NADIP_ID_NADIP int NOT NULL PRIMARY KEY, NADIP_NATURE_DILIGENCE varchar(10) NOT NULL,
        NADIP_CODE_PROCESSUS varchar(64) NULL, NADIP_NUM_ORDRE int NULL, NADIP_CODE_PARAM varchar(128) NOT NULL,
        NADIP_VALEUR_PARAM varchar(max) NOT NULL);
-- Le type du parametre (CritereMetier...), que PROC_DCA_RELANCE.sql (qui cree la table) ne pose pas : NVARCHAR(32) de RIG_DEV.
IF COL_LENGTH('v2.NATURE_DILIGENCE_PARAM', 'NADIP_TYPE_PARAM') IS NULL ALTER TABLE v2.NATURE_DILIGENCE_PARAM ADD NADIP_TYPE_PARAM varchar(32) NULL;
-- (sp_executesql : les colonnes ajoutees ci-dessus ne sont connues qu'apres la compilation de ce lot.)
EXEC sp_executesql N'
INSERT INTO v2.NATURE_DILIGENCE_GROUPE (NDILGRP_ID_NDILGRP, NDILGRP_CODE, NDILGRP_LIBELLE) VALUES (2000002, ''JugeCommis'', ''Surveillances Juge Commis'');
INSERT INTO v2.NATURE_DILIGENCE (R_NATUREDILI_VALEUR, R_NATUREDILI_LIBELLE_ECRAN, R_NATUREDILI_ID_NDILGRP) VALUES (''SJC20'', ''Surveillance juge commis du banc'', 2000002);
INSERT INTO v2.NATURE_DILIGENCE_PARAM (NADIP_ID_NADIP, NADIP_NATURE_DILIGENCE, NADIP_TYPE_PARAM, NADIP_CODE_PARAM, NADIP_VALEUR_PARAM) VALUES
    (2000001, ''SDCA'', ''CritereMetier'', ''CodeAffaire'', ''POP20''), (2000002, ''SDBE'', ''CritereMetier'', ''CodeAffaire'', ''INJRBE20''),
    (2000003, ''SJC20'', ''CritereMetier'', ''CodeAffaire'', ''JCOM20''), (2000004, ''SDCA'', ''CritereMetier'', ''NatureAffaire'', ''OPIDC'');';

-- Les bornes de la recherche (PARAMETRAGE ORDOSIGN_DATE_DEBUT_*, repris dans soc.Reglage) et le code affaire du changement de juge.
INSERT INTO soc.Reglage (Code, Libelle, Valeur)
SELECT c, 'Banc EcransGeneresBase lot 10', v FROM (VALUES ('ORDOSIGN_DATE_DEBUT_OP', '01/01/2021'), ('ORDOSIGN_DATE_DEBUT_IP', '12/01/2016'),
    ('ORDOSIGN_DATE_DEBUT_JC', '01/10/2017'), ('ORDOSIGN_DATE_DEBUT_PRV', '22/01/2018'), ('ORDOSIGN_DATE_DEBUT_IDCA', '22/01/2018'),
    ('ORDOSIGN_DATE_DEBUT_IDBE', '01/05/2021'), ('CHJCM_CODE_AFFAIRE', 'OPCHJ20')) AS r (c, v)
WHERE NOT EXISTS (SELECT 1 FROM soc.Reglage AS x WHERE x.Code = r.c);

