-- Les decisions, une par instance (prevues dans l'ordre des roles). 2000104 rendue l'an dernier, 2000105 rendue le jour du banc ;
-- 2000118 porte deja la minute 2501000001 (le 10/01/2025), sans date.
EXEC sp_executesql N'
INSERT INTO v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC, DCJDC_ID_INSTN, DCJDC_NUM_ORDRE, DCJDC_DATE_PREVUE, DCJDC_DATE, DCJDC_TYPE_DECISION, DCJDC_NUM_REPERTOIRE)
SELECT INSTN_ID_INSTN, INSTN_ID_INSTN, 1, DATEADD(day, INSTN_ID_INSTN - 2000100, @aujourdhui),
       CASE INSTN_ID_INSTN WHEN 2000104 THEN DATEADD(year, -1, @aujourdhui) WHEN 2000105 THEN @aujourdhui END,
       CASE WHEN INSTN_ID_INSTN IN (2000101, 2000106, 2000118) THEN ''OPOS20'' ELSE ''OPSANS20'' END,
       CASE INSTN_ID_INSTN WHEN 2000118 THEN ''2501000001'' END
FROM v2.INSTANCE WHERE INSTN_ID_INSTN BETWEEN 2000101 AND 2000120;', N'@aujourdhui datetime', @aujourdhui;

-- 2000113 a une relance RCS (« on exclu toutes les instances liées à une relance », :787) ; 2000103 est verrouillee par une demande en
-- cours de RIG v2 (DOSSIER_DEMANDE 2J).
EXEC sp_executesql N'
INSERT INTO v2.RELANCE_RCS (RLCRC_ID_RLCRC, RLCRC_ID_DLGRC, RLCRC_NUM_ORDRE, RLCRC_DATE_RELANCE, RLCRC_ID_INSTN) VALUES (2000113, NULL, 1, ''2020-02-01'', 2000113);
