-- CE QUE LA SIGNATURE ECRIT (lot 10, apres la reception du chef ; OPE_LISTE_ORDONNANCES._DoGenererLignesEditionStandard, :2581-2960, et
-- _DoSauver, :3311-3402). Le type d'une decision porte son evenement de procedure (R_TYPEDECISI_CODE_EVE_PRO) et sa mesure liee
-- (R_TYPEDECISI_TYPE_MESURE_LIE) ; l'evenement porte ses maquettes d'edition (CEP_EDITION) et l'evenement de la PC (CODE_EVE_PRO_PC).
-- Colonnes aux types de RIG_DEV (lu le 27/11/2026), s'il manque ; EVENEMENT_PROCEDURE, CODE_EVE_PRO, CEP_EDITION, PARAMETRE_EDITION,
-- DESTINATAIRE_INSTITUTIONNEL et leurs colonnes viennent de PROC_GCONV.sql et PROC_MESIN.sql (joues avant) et de PROC_RETAUD.sql (les
-- delais du code futur, joue apres, avant les gestes).
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_CODE_EVE_PRO') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_CODE_EVE_PRO varchar(10) NULL;
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_TYPE_MESURE_LIE') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_TYPE_MESURE_LIE varchar(5) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_CODE_EVE_PRO_PC') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_CODE_EVE_PRO_PC varchar(10) NULL;
IF COL_LENGTH('v2.MESURE', 'MSINS_NUM_ORDRE') IS NULL ALTER TABLE v2.MESURE ADD MSINS_NUM_ORDRE smallint NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_ID_DMND_MERE') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_ID_DMND_MERE int NULL;
-- La tarification (definition de PROC_RETAUD.sql, joue apres), plus le numero de facture que la signature lit (ListeArticlesTarifes :
-- ARTUT_NUMERO_FACTURE vide, Facture\Affaire.cs:99-109), s'il manque.
IF OBJECT_ID(N'v2.ARTICLE_UTILISE') IS NULL
    CREATE TABLE v2.ARTICLE_UTILISE (ARTUT_ID_ARTUT int NOT NULL PRIMARY KEY, ARTUT_ID_AFFRE int NULL, ARTUT_MONTANT_TTC money NOT NULL,
        ARTUT_ID_INSTN int NULL, ARTUT_ID_CLIEN int NULL, ARTUT_CODE_ARTICLE varchar(32) NULL, ARTUT_PRIX_UHT money NULL,
        ARTUT_QUANTITE smallint NULL, ARTUT_MONTANT_INPI money NULL, ARTUT_MONTANT_BODACC money NULL, ARTUT_MONTANT_AUTRE money NULL,
        ARTUT_DATE_CREATION datetime NULL);
IF COL_LENGTH('v2.ARTICLE_UTILISE', 'ARTUT_NUMERO_FACTURE') IS NULL ALTER TABLE v2.ARTICLE_UTILISE ADD ARTUT_NUMERO_FACTURE varchar(25) NULL;
-- Les factures (definition de PROC_RECHERCHE_GED.sql) et les pieces numerisees (definition de PROC_SDEMATJUD.sql), joues apres : s'il manque.
IF OBJECT_ID(N'v2.FACTURE') IS NULL
    CREATE TABLE v2.FACTURE (FACTU_NUMERO_FACTURE varchar(25) NOT NULL PRIMARY KEY, FACTU_NUM_DEMANDE varchar(32) NOT NULL);
IF OBJECT_ID(N'v2.VIDIGED_INDEX') IS NULL
    CREATE TABLE v2.VIDIGED_INDEX (VGIDX_ID_VGIDX int NOT NULL PRIMARY KEY, VGIDX_ID_ENTITE int NULL, VGIDX_TYPE_ENTITE varchar(50) NULL,
        VGIDX_ID_DCJDC int NULL, VGIDX_ID_PBLCT int NULL, VGIDX_NATURE_DOC varchar(50) NULL, VGIDX_DATE_RECEPTION datetime NULL);
-- Les types et leurs evenements :
--   OPOS20 (2000101, 2000118) : l'evenement OSEVE20, dont la maquette OS20NOTIF va au document interne (« DI » : lettre simple), et
--     une expertise liee EXP20 ;
--   OPPC20 (2000106, avec PC) : l'evenement OSPC20, qui porte l'evenement OSPCX20 de la PC -- refuse ; jumeau : OPOS20 (sans evenement de PC) ;
--   OPLR20 (2000114) : l'evenement OSLR20, dont la maquette va au demandeur par LRAR (« D,LRAR ») -- refuse ; jumeau : OS20NOTIF.
-- OPPC20 et OPLR20 gardent le libelle de leur ancien type : la liste (PROC_ORDOSIGN.attendu) ne change pas.
EXEC sp_executesql N'
UPDATE v2.TYPE_DECISION SET R_TYPEDECISI_CODE_EVE_PRO = ''OSEVE20'', R_TYPEDECISI_TYPE_MESURE_LIE = ''EXP20'' WHERE R_TYPEDECISI_VALEUR = ''OPOS20'';
